549	// countCells counts all cell directories under the given path.
550	func countCells(t *testing.T, baseDir string) int {
551		count := 0
552		filepath.Walk(baseDir, func(path string, info os.FileInfo, err error) error {
553			if err != nil {
554				return nil
555			}
556			if info.IsDir() && isCellDirectory(path) {
557				count++
558			}
559			return nil
560		})
561		return count
562	}
