564	// isCellDirectory checks if a directory looks like a cell directory (contains report.json or cell-state.json).
565	func isCellDirectory(path string) bool {
566		reportPath := filepath.Join(path, "report.json")
567		if _, err := os.Stat(reportPath); err == nil {
568			return true
569		}
570	
571		statePath := filepath.Join(path, "cell-state.json")
572		if _, err := os.Stat(statePath); err == nil {
573			return true
574		}
575	
576		return false
577	}
